async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') return answerListSessions(ws, session, sessionStore, message);
}

// Answered here, not under the lock: a history request is not a turn and must not queue behind a streaming answer.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  // A store that cannot list at all answers an empty list, not a failure: the frame is served, the store just has none.
  if (sessionStore?.listFor === undefined) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    sendSessionList(ws, summaries.map(summaryFrame));
  } catch (error) {
    // The store's own detail stays out of the frame: it names a database, and the frame names the user's request.
    const detail = error instanceof Error ? error.message : String(error);
    log.error('ws', 'listing conversations failed', {userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
  }
}

// The wire carries ISO strings: a Date does not survive JSON.stringify as a Date.
function summaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
  try {
    await action();
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    const code = error instanceof AIError ? error.code : 'UNKNOWN';
    log.error('message', 'handling error', {error: message, code});
